CREATE POLICY "office images readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'office-images');
CREATE POLICY "office images insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'office-images' AND public.can_manage(auth.uid(),'content_admin'));
CREATE POLICY "office images update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'office-images' AND public.can_manage(auth.uid(),'content_admin')) WITH CHECK (bucket_id = 'office-images' AND public.can_manage(auth.uid(),'content_admin'));
CREATE POLICY "office images delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'office-images' AND public.can_manage(auth.uid(),'content_admin'));